/**
 * Valida el cuerpo que envía HelpDesk (src/server/portal/portal-mail.ts) y
 * arma el mensaje de Microsoft Graph. n8n transporta: no decide a quién ni qué
 * se envía; eso ya lo decidió PostgreSQL y la aplicación.
 *
 * Remitente: el buzón automatizacionmedellin@, que va en la URL del nodo HTTP
 * (/users/<buzón>/sendMail). El buzón no tiene inicio de sesión propio: la
 * credencial OAuth2 la autoriza una persona con Send As sobre él, con el
 * permiso delegado Mail.Send.Shared.
 *
 * saveToSentItems: false a propósito. El cuerpo lleva un código o un enlace de
 * un solo uso: una copia en Elementos enviados del buzón sería otro sitio donde
 * el secreto queda en claro.
 */
const body = $input.first().json.body ?? {};
// ESCALAMIENTO (U15): el correo diario a un empleado con avisos sin atender.
const kinds = ['INVITACION', 'CODIGO', 'ESCALAMIENTO'];
const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (body.event !== 'helpdesk.portal.correo') throw new Error('Evento no soportado.');
if (body.version !== 1) throw new Error('Versión de mensaje no soportada.');
if (!kinds.includes(body.kind)) throw new Error('Tipo de correo no soportado.');
if (typeof body.id !== 'string' || body.id.length === 0) throw new Error('Falta el id de correlación.');
if (typeof body.to !== 'string' || !email.test(body.to)) throw new Error('Destinatario inválido.');
if (typeof body.subject !== 'string' || body.subject.length === 0) throw new Error('Falta el asunto.');
if (typeof body.html !== 'string' || body.html.length === 0) throw new Error('Falta el cuerpo.');

return [
  {
    json: {
      id: body.id,
      graph: {
        message: {
          subject: body.subject,
          body: { contentType: 'HTML', content: body.html },
          toRecipients: [{ emailAddress: { address: body.to } }],
        },
        saveToSentItems: false,
      },
    },
  },
];
